		refs, moreDiags := langrefs.ReferencesInExpr(addrs.ParseRef, forEachExpr)
		forEachDiags = forEachDiags.Append(moreDiags)
		scope := ctx.EvaluationScope(nil, nil, EvalDataForNoInstanceKey)
		if scope != nil {
			hclCtx, moreDiags = scope.EvalContext(refs)
		} else {
			hclCtx = &hcl.EvalContext{}
		}
		forEachDiags = forEachDiags.Append(moreDiags)
		if forEachDiags.HasErrors() {
			diags = diags.Append(forEachDiags)
			return knownImports, unknownImports, diags
		}

		forEachVal, valDiags := forEachExpr.Value(hclCtx)
		forEachDiags = forEachDiags.Append(valDiags)
		if forEachDiags.HasErrors() {
			diags = diags.Append(forEachDiags)
			return knownImports, unknownImports, diags
		}

		if !forEachVal.IsWhollyKnown() {
			unknownDiags := forEachDiags.Append(&hcl.Diagnostic{
				Severity:    hcl.DiagError,
				Summary:     "Invalid for_each argument",
				Detail:      "The \"for_each\" expression includes values derived from other resource attributes that cannot be determined until apply, and so Terraform cannot determine the full set of values that might be used to import this resource.",
				Subject:     forEachExpr.Range().Ptr(),
				Expression:  forEachExpr,
				EvalContext: hclCtx,
				Extra:       diagnosticCausedByUnknown(true),
			})
			if !allowUnknown {
				forEachDiags = forEachDiags.Append(unknownDiags)
			}
			known = false
		} else if !forEachVal.IsNull() {
			val, valMarks := forEachVal.Unmark()
			it := val.ElementIterator()
			for it.Next() {
				k, v := it.Element()
				forEachData = append(forEachData, instances.RepetitionData{
					EachKey:   k,
					EachValue: v.WithMarks(valMarks),
				})
			}
		}

