			// Then we need to parse the target address as a PartialResource
			// instead of a known resource.
			var addr addrs.PartialExpandedResource
			unknownKeys := instances.UnknownForEachRepetitionData(cty.DynamicPseudoType)
			traversal, evalDiags := importToExprToTraversal(imp.Config.To, unknownKeys)
			diags = diags.Append(evalDiags)
			if !diags.HasErrors() {
				partial, rest, parseDiags := addrs.ParsePartialExpandedResource(traversal)
				diags = diags.Append(parseDiags)
				if !parseDiags.HasErrors() {
					if len(rest) > 0 {
						diags = diags.Append(&hcl.Diagnostic{
							Severity: hcl.DiagError,
							Summary:  "Invalid import 'to' expression",
							Detail:   "The import block 'to' argument does not resolve to a single resource instance.",
							Subject:  traversal.SourceRange().Ptr(),
